import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Card,
  Container,
  Row,
  Col,
  Form,
} from "react-bootstrap";
import "chartist/dist/chartist.min.css";

//============= STYLE ===============
const themeStyle = `
.chart-scroll {
  overflow-x: auto;
  overflow-y: hidden;
}
.history-header {
  background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%) !important;
  border-radius: 8px 8px 0 0 !important;
  padding: 20px !important;
}
.history-header .card-title {
  color: white !important;
  margin: 0 !important;
  font-weight: bold;
}
.card {
  border: none !important;
  box-shadow: 0 0 2rem 0 rgba(136,152,170,.15) !important;
  border-radius: .75rem !important;
}
.form-label {
  font-weight: 700;
  color: #5e72e4;
  font-size: .75rem;
}
`;

// ================= UTILS =================
const timeToSeconds = (time) => {
  const [h, m, s] = time.split(":").map(Number);
  return h * 3600 + m * 60 + s;
};

// ===== aggregate ทุก 5 วินาที =====
const aggregate5Seconds = (labels, series) => {
  const bucket = {};

  labels.forEach((label, idx) => {
    const [h, m, s] = label.split(":").map(Number);
    const sec = Math.floor(s / 5) * 5;

    const key = `${h.toString().padStart(2, "0")}:` +
                `${m.toString().padStart(2, "0")}:` +
                `${sec.toString().padStart(2, "0")}`;

    if (!bucket[key]) {
      bucket[key] = { sum: 0, count: 0 };
    }
    bucket[key].sum += series[idx];
    bucket[key].count += 1;
  });

  const labelsOut = [];
  const seriesOut = [];

  Object.keys(bucket)
    .sort((a, b) => timeToSeconds(a) - timeToSeconds(b))
    .forEach((key) => {
      const avg = Math.round(bucket[key].sum / bucket[key].count);
      labelsOut.push(key);
      seriesOut.push(avg >= 20 ? avg : null); // ต่ำกว่า 20 ไม่แสดงแท่ง
    });

  return { labels: labelsOut, series: [seriesOut] };
};

// ================= MAIN =================
function History() {
  const [cameraId, setCameraId] = useState("CAM01");
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });

  const handleSearch = async () => {
    const API_BASE = "http://localhost:3001";
    try {
      const res = await fetch(`${API_BASE}/api/history?cameraId=${cameraId}`);
      const result = await res.json();

      if (result?.labels?.length) {
        const aggregated = aggregate5Seconds(
          result.labels,
          result.series[0]
        );
        setChartState(aggregated);
      }
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    handleSearch();
  }, [cameraId]);

  // ===== CHART OPTIONS =====
  const barChartOptions = {
    height: "400px",
    axisX: {
      showGrid: false,
      offset: 70,
      labelInterpolationFnc: (value, index) =>
        index % 12 === 0 ? value : null, // แสดงทุก 1 นาที
    },
    axisY: {
      onlyInteger: true,
      low: 0,
    },
    fullWidth: true,
  };

  // ===== BAR COLOR =====
  const drawBarLabels = (data) => {
    if (data.type === "bar" && data.value.y !== null) {
      const color = data.value.y >= 40
        ? "#f5365c"
        : data.value.y >= 30
        ? "#fb6340"
        : "#2dce89";

      data.element.attr({
        style: `stroke:${color}; stroke-width:30px;`,
      });
    }
  };

  return (
    <Container fluid className="py-4">
      <style>{themeStyle}</style>

      <Row>
        <Col md="12">
          <Card>
            <Card.Header className="history-header">
              <Card.Title as="h4">ค้นหาข้อมูลย้อนหลัง</Card.Title>
            </Card.Header>
            <Card.Body>
              <Form.Select
                value={cameraId}
                onChange={(e) => setCameraId(e.target.value)}
              >
                <option value="CAM01">วิศวะ</option>
                <option value="CAM02">วิทยาศาสตร์</option>
                <option value="CAM03">ศิลปศาสตร์</option>
                <option value="CAM04">PKY</option>
              </Form.Select>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {chartState.labels.length > 0 && (
        <Row>
          <Col md="12">
            <Card>
              <Card.Body>
                <div className="chart-scroll">
                  <div style={{ width: chartState.labels.length * 60 }}>
                    <ChartistGraph
                      data={chartState}
                      type="Bar"
                      options={barChartOptions}
                      listener={{ draw: drawBarLabels }}
                    />
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
